    for (int i = 2; i * i <= n; i++) {
        if (isPrime[i]) {
            for (int j = i * i; j <= n; j += i) {
                isPrime[j] = false;
            }
        }
    }
    int sum = 0;
    for (int i = 2; i <= n; i++) {
        if (isPrime[i]) {
            sum += i;
        }
    }
