int largestPowerOf2(int x) {
    int power = 0;
    while ((1 << (power + 1)) <= x) {
        power++;
    }
    return power;
}

int countSetBitsUtil(int x) {
    if (x == 0)
        return 0;
    int power = largestPowerOf2(x);
    int bitsUpToPower = power * (1 << (power - 1));
    int mostSignificantBits = x - (1 << power) + 1;
    return bitsUpToPower + mostSignificantBits + countSetBitsUtil(x - (1 << power));
}

int countSetBits(int n) {
    return countSetBitsUtil(n);
}

